cat <<'EOF' > check_console.js
const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  page.on('console', msg => {
    console.log(`CONSOLE_${msg.type().toUpperCase()}: ${msg.text()}`);
  });
  page.on('pageerror', err => {
    console.log(`PAGE_ERROR: ${err.message}`);
  });
  await page.goto('http://localhost:3000');
  await page.waitForTimeout(2000);
  console.log('--- Clicking Button ---');
  await page.click('#connect-slack');
  await page.waitForTimeout(3000);
  const status = await page.innerText('#status');
  console.log(`STATUS_TEXT: ${status}`);
  const iframeVisible = await page.isVisible('#paragon-connect-frame');
  console.log(`IFRAME_VISIBLE: ${iframeVisible}`);
  const iframeStyle = await page.getAttribute('#paragon-connect-frame', 'style');
  console.log(`IFRAME_STYLE: ${iframeStyle}`);
  await browser.close();
})();
EOF
node check_console.js

